import Foundation
import Compression
import CryptoKit

// MARK: - Audit Log Entry
struct AuditLogEntry: Codable {
    let timestamp: Date
    let userId: String
    let action: String
    let metadata: [String: String]
}

// MARK: - Compressed Audit Store
class CompressedAuditStore {
    private let maxRawEntrySize: Int = 4096
    private let maxCompressedBatchSize: Int = 1024 * 1024 // 1MB compressed
    private var storePath: URL

    init(storePath: URL) {
        self.storePath = storePath
    }

    func writeEntry(_ entry: AuditLogEntry) throws {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        let data = try encoder.encode(entry)
        guard data.count <= maxRawEntrySize else {
            throw AuditError.entrySizeExceeded
        }
        let compressed = try compress(data: data)
        try compressed.write(to: storePath.appendingPathComponent(UUID().uuidString + ".zlog"))
    }
}

// MARK: - Authentication Token with Embedded Audit Proof
struct AuthToken: Codable {
    let subject: String
    let issuedAt: Date
    let expiresAt: Date
    let auditProof: Data // compressed audit chain
    let signature: Data // HMAC-SHA256 over canonical token contents
}

// MARK: - Token Validator
class TokenValidator {
    private let maxCompressedProofSize: Int = 64 * 1024 // 64KB compressed input limit
    private let maxDecompressedSize: Int = 2 * 1024 * 1024 // 2MB absolute max output
    private let decompressionBufferSize: Int = 65536

    /// Validates the audit proof embedded in the token.
    /// The proof is a compressed JSON array of prior audit entries.
    func validateAuditProof(token: AuthToken) throws -> [AuditLogEntry] {
        let compressedData = token.auditProof

        // Gate 1: Check compressed size
        guard compressedData.count <= maxCompressedProofSize else {
            throw AuditError.proofTooLarge
        }

        // Gate 2: Decompress with streaming approach
        let decompressed = try decompressStream(data: compressedData)

        // Gate 3: Parse entries
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        let entries = try decoder.decode([AuditLogEntry].self, from: decompressed)

        // Gate 4: Validate chain integrity
        guard entries.count <= 1000 else {
            throw AuditError.chainTooLong
        }

        return entries
    }

    /// Streaming decompression with absolute size limit.
    /// Regardless of input size, output is capped at maxDecompressedSize.
    private func decompressStream(data: Data) throws -> Data {
        let maxOutputSize = maxDecompressedSize

        var decompressed = Data()
        let pageSize = decompressionBufferSize

        try data.withUnsafeBytes { (srcBuffer: UnsafeRawBufferPointer) in
            let srcPointer = srcBuffer.bindMemory(to: UInt8.self)
            guard let srcBase = srcPointer.baseAddress else {
                throw AuditError.decompressionFailed
            }

            let dstBuffer = UnsafeMutablePointer<UInt8>.allocate(capacity: pageSize)
            defer { dstBuffer.deallocate() }

            let stream = UnsafeMutablePointer<compression_stream>.allocate(capacity: 1)
            defer { stream.deallocate() }

            var status = compression_stream_init(stream, COMPRESSION_STREAM_DECODE, COMPRESSION_ZLIB)
            guard status != COMPRESSION_STATUS_ERROR else {
                throw AuditError.decompressionFailed
            }
            defer { compression_stream_destroy(stream) }

            stream.pointee.src_ptr = srcBase
            stream.pointee.src_size = data.count
            stream.pointee.dst_ptr = dstBuffer
            stream.pointee.dst_size = pageSize

            repeat {
                status = compression_stream_process(stream, 0)

                let outputBytes = pageSize - stream.pointee.dst_size
                if outputBytes > 0 {
                    decompressed.append(dstBuffer, count: outputBytes)
                    stream.pointee.dst_ptr = dstBuffer
                    stream.pointee.dst_size = pageSize
                }

                // Check decompressed size against absolute limit
                if decompressed.count > maxOutputSize {
                    throw AuditError.decompressionBombDetected
                }

            } while status == COMPRESSION_STATUS_OK

            if status == COMPRESSION_STATUS_ERROR {
                throw AuditError.decompressionFailed
            }
        }

        return decompressed
    }
}

// MARK: - Authentication Service
class AuthenticationService {
    private let tokenValidator = TokenValidator()
    private let auditStore: CompressedAuditStore
    private let signingKey: SymmetricKey

    init(auditStorePath: URL, signingKey: SymmetricKey) {
        self.auditStore = CompressedAuditStore(storePath: auditStorePath)
        self.signingKey = signingKey
    }

    /// Computes the canonical bytes that the token signature covers.
    private func canonicalTokenBytes(_ token: AuthToken) -> Data {
        var buffer = Data()
        buffer.append(Data(token.subject.utf8))
        buffer.append(Data("|".utf8))
        buffer.append(Data(String(token.issuedAt.timeIntervalSince1970).utf8))
        buffer.append(Data("|".utf8))
        buffer.append(Data(String(token.expiresAt.timeIntervalSince1970).utf8))
        buffer.append(Data("|".utf8))
        buffer.append(token.auditProof)
        return buffer
    }

    /// Verifies the token's HMAC signature in constant time.
    private func verifySignature(_ token: AuthToken) -> Bool {
        let expected = HMAC<SHA256>.authenticationCode(
            for: canonicalTokenBytes(token),
            using: signingKey
        )
        return HMAC<SHA256>.isValidAuthenticationCode(
            token.signature,
            authenticating: canonicalTokenBytes(token),
            using: signingKey
        ) && Data(expected).count > 0
    }

    func authenticate(tokenData: Data) throws -> String {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        let token = try decoder.decode(AuthToken.self, from: tokenData)

        // Verify token authenticity/integrity BEFORE trusting any of its contents
        guard verifySignature(token) else {
            throw AuditError.invalidSignature
        }

        // Verify expiration
        guard token.expiresAt > Date() else {
            throw AuditError.tokenExpired
        }

        // Validate audit proof chain
        let auditEntries = try tokenValidator.validateAuditProof(token: token)

        // Log successful authentication
        let entry = AuditLogEntry(
            timestamp: Date(),
            userId: token.subject,
            action: "authenticate",
            metadata: ["proof_entries": "\(auditEntries.count)"]
        )
        try auditStore.writeEntry(entry)

        return token.subject
    }
}

// MARK: - Compression Utility
func compress(data: Data) throws -> Data {
    var compressed = Data()
    let pageSize = 65536

    try data.withUnsafeBytes { (srcBuffer: UnsafeRawBufferPointer) in
        let srcPointer = srcBuffer.bindMemory(to: UInt8.self)
        guard let srcBase = srcPointer.baseAddress else {
            throw AuditError.compressionFailed
        }

        let dstBuffer = UnsafeMutablePointer<UInt8>.allocate(capacity: pageSize)
        defer { dstBuffer.deallocate() }

        let stream = UnsafeMutablePointer<compression_stream>.allocate(capacity: 1)
        defer { stream.deallocate() }

        var status = compression_stream_init(stream, COMPRESSION_STREAM_ENCODE, COMPRESSION_ZLIB)
        guard status != COMPRESSION_STATUS_ERROR else {
            throw AuditError.compressionFailed
        }
        defer { compression_stream_destroy(stream) }

        stream.pointee.src_ptr = srcBase
        stream.pointee.src_size = data.count
        stream.pointee.dst_ptr = dstBuffer
        stream.pointee.dst_size = pageSize

        repeat {
            status = compression_stream_process(stream, Int32(COMPRESSION_STREAM_FINALIZE.rawValue))
            let outputBytes = pageSize - stream.pointee.dst_size
            if outputBytes > 0 {
                compressed.append(dstBuffer, count: outputBytes)
                stream.pointee.dst_ptr = dstBuffer
                stream.pointee.dst_size = pageSize
            }
        } while status == COMPRESSION_STATUS_OK

        if status == COMPRESSION_STATUS_ERROR {
            throw AuditError.compressionFailed
        }
    }

    return compressed
}

// MARK: - Errors
enum AuditError: Error {
    case entrySizeExceeded
    case proofTooLarge
    case chainTooLong
    case decompressionFailed
    case decompressionBombDetected
    case compressionFailed
    case tokenExpired
    case invalidSignature
}
